import { test as base } from "../helpers/system-control-browser";
import "dotenv/config";
import { expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";
import { Pool } from "pg";
import { randomUUID } from "node:crypto";
import { encode } from "next-auth/jwt";
import { requireTestDatabaseUrl } from "../helpers/foundation-db";
requireTestDatabaseUrl();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const test = base.extend<{
  operator: {
    actor: string;
    target: string;
    sentinels: string[];
    setSession: (fresh: boolean) => Promise<void>;
  };
}>({
  operator: async ({ context }, runFixture) => {
    const actor = randomUUID(),
      target = randomUUID(),
      sentinels = [
        "TOKEN",
        "SUBJECT",
        "BODY",
        "CONTACT",
        "PATH",
        "WEBHOOK",
      ].map((x) => `${x}-PRIVATE-${randomUUID()}`);
    await pool.query(
      `INSERT INTO "User" (id,email,name,"googleId","encryptedRefreshToken","isAdmin","usageBackfillVersion") VALUES ($1,$2,'Browser Operator',$3,$4,true,1)`,
      [actor, `${actor}@example.test`, sentinels[1], sentinels[0]],
    );
    await pool.query(
      `INSERT INTO "User" (id,email,name,"googleId","encryptedRefreshToken","usageBackfillVersion") VALUES ($1,$2,'Browser Target',$3,$4,1)`,
      [target, `${target}@example.test`, sentinels[1] + "target", sentinels[0]],
    );
    await pool.query(
      `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Private template',$3,$3)`,
      [randomUUID(), target, sentinels[2]],
    );
    await pool.query(
      `INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)`,
      [randomUUID(), target, sentinels[3], `${target}@private.test`],
    );
    await pool.query(
      `INSERT INTO "Attachment" (id,"userId","fileName","storagePath") VALUES ($1,$2,'Private resume.pdf',$3)`,
      [randomUUID(), target, sentinels[4]],
    );
    const webhookId = randomUUID();
    await pool.query(
      `INSERT INTO "BillingWebhookEvent" (id,"webhookId","eventType","businessId","occurredAt","normalizedData","payloadHash") VALUES ($1,$1,'test','test',now(),$2,$3)`,
      [webhookId, JSON.stringify({ secret: sentinels[5] }), "a".repeat(64)],
    );
    const setSession = async (fresh: boolean) => {
      const salt = "authjs.session-token";
      const token = await encode({
        secret: process.env.AUTH_SECRET!,
        salt,
        token: {
          userId: actor,
          sub: actor,
          adminAuthAt: Math.floor(Date.now() / 1000) - (fresh ? 0 : 901),
          adminAuthUserId: actor,
        },
      });
      await context.addCookies([
        {
          name: salt,
          value: token,
          domain: "localhost",
          path: "/",
          httpOnly: true,
          sameSite: "Lax",
        },
      ]);
    };
    await setSession(true);
    try {
      await runFixture({ actor, target, sentinels, setSession });
    } finally {
      await pool.query('DELETE FROM "User" WHERE id=ANY($1)', [
        [actor, target],
      ]);
      await pool.query('DELETE FROM "BillingWebhookEvent" WHERE id=$1', [
        webhookId,
      ]);
      await pool.query(
        `UPDATE "SystemControl" SET "sendingEnabled"=true,"updatedAt"=now() WHERE key='global'`,
      );
    }
  },
});
test.use({ reducedMotion: "reduce" });
test.afterAll(async () => {
  await pool.end();
});
test("protects every operator page from anonymous access", async ({
  browser,
  operator,
}) => {
  const context = await browser.newContext(),
    page = await context.newPage();
  for (const path of [
    "/admin",
    "/admin/users",
    `/admin/users/${operator.target}`,
    "/admin/audit",
    "/admin/controls",
  ]) {
    await page.goto(path);
    await expect(page).toHaveURL("/");
  }
  await context.close();
});
test("renders safe pages and payloads, applies one suspension for repeated clicks, and supports audit filters", async ({
  page,
  operator,
}) => {
  const bodies: Promise<string>[] = [];
  page.on("response", (r) => {
    if (new URL(r.url()).pathname.startsWith("/admin"))
      bodies.push(r.text().catch(() => ""));
  });
  for (const [path, title] of [
    ["/admin", "Operator panel"],
    ["/admin/users", "Users"],
    [`/admin/users/${operator.target}`, "Browser Target"],
    ["/admin/audit", "Audit history"],
    ["/admin/controls", "Sending controls"],
  ]) {
    await page.goto(path);
    if (path === "/admin/users" || path === "/admin/audit") {
      const heading = page.locator("th").first();
      await expect(heading).toHaveCSS("border-bottom-style", "dotted");
      await expect(heading).toHaveCSS("border-bottom-width", "1px");
    }
    await expect(
      page.getByRole("heading", { name: title, exact: true }),
    ).toBeVisible();
    await expect(page.locator("body")).not.toContainText(
      "Admin data is unavailable",
    );
  }
  await page.goto(`/admin/users/${operator.target}`);
  await page
    .getByRole("button", { name: "Suspend account", exact: true })
    .dblclick();
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: /Change saved|Verify your Google identity/ }),
  ).toContainText("Change saved.");
  await expect(
    page.getByRole("button", { name: "Unsuspend account" }),
  ).toBeVisible();
  expect(
    (
      await pool.query(
        `SELECT count(*)::int AS n FROM "AdminAuditSafe" WHERE "targetIdSnapshot"=$1 AND action='SUSPENSION'`,
        [operator.target],
      )
    ).rows[0].n,
  ).toBe(1);
  await page.goto(`/admin/audit?targetId=${operator.target}`);
  await expect(page.getByRole("table")).toContainText("SUSPENSION");
  await page.goto(`/admin/users?search=${operator.target}`);
  await expect(page.getByRole("table")).toContainText("Browser Target");
  const html = (await Promise.all(bodies)).join("\n");
  for (const sentinel of operator.sentinels)
    expect(html).not.toContain(sentinel);
  const axe = await new AxeBuilder({ page }).analyze();
  expect(axe.violations).toEqual([]);
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth,
    ),
  ).toBe(true);
});
test("enforces freshness and current role after session issuance", async ({
  page,
  operator,
}) => {
  await operator.setSession(false);
  await page.goto(`/admin/users/${operator.target}`);
  await page
    .getByRole("button", { name: "Suspend account", exact: true })
    .click();
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: /Change saved|Verify your Google identity/ }),
  ).toContainText("Verify your Google identity");
  expect(
    (
      await pool.query('SELECT "isSuspended" FROM "User" WHERE id=$1', [
        operator.target,
      ])
    ).rows[0].isSuspended,
  ).toBe(false);
  await pool.query('UPDATE "User" SET "isAdmin"=false WHERE id=$1', [
    operator.actor,
  ]);
  await page.goto("/admin/audit");
  await expect(page).toHaveURL("/compose");
});
test("requires kill-switch confirmation and saves an audited global control", async ({
  page,
  operator,
}) => {
  await page.goto("/admin/controls");
  await page.getByLabel(/I confirm I want to disable/).check();
  await page.getByRole("button", { name: "Disable all sending" }).click();
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: /Change saved|Verify your Google identity/ }),
  ).toContainText("Change saved.");
  await expect(
    page.getByRole("button", { name: "Enable sending", exact: true }),
  ).toBeVisible();
  expect(
    (
      await pool.query(
        'SELECT "sendingEnabled" FROM "SystemControl" WHERE key=\'global\'',
      )
    ).rows[0].sendingEnabled,
  ).toBe(false);
  expect(
    (
      await pool.query(
        `SELECT count(*)::int AS n FROM "AdminAuditSafe" WHERE "actorIdSnapshot"=$1 AND action='SENDING_CONTROL'`,
        [operator.actor],
      )
    ).rows[0].n,
  ).toBe(1);
});

test("retains override values and request UUID across a failed audit and retry", async ({
  page,
  operator,
}) => {
  await page.goto(`/admin/users/${operator.target}`);
  await page.getByRole("combobox", { name: /^Override/ }).selectOption("PAID");
  const expires = new Date(Date.now() + 7 * 86400000).toISOString();
  await page.getByLabel("Expires at (UTC; blank means 30 days)").fill(expires);
  await page
    .getByRole("combobox", { name: /^Reason/ })
    .first()
    .selectOption("SECURITY");
  const trigger = "browser_retry_" + operator.target.replaceAll("-", "");
  const requests: string[] = [];
  page.on("request", (request) => {
    if (
      request.method() === "POST" &&
      new URL(request.url()).pathname.startsWith("/admin")
    ) {
      const body = request.postData() ?? "";
      const match = body.match(/"requestId":"([a-f0-9-]{36})"/);
      if (match) requests.push(match[1]);
    }
  });
  await pool.query(
    `CREATE FUNCTION "${trigger}"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."targetIdSnapshot"='${operator.target}' THEN RAISE EXCEPTION 'FIXED_TEST_AUDIT_FAILURE'; END IF; RETURN NEW; END $$; CREATE TRIGGER "${trigger}" BEFORE INSERT ON "AdminAuditLog" FOR EACH ROW EXECUTE FUNCTION "${trigger}"()`,
  );
  try {
    await page.getByRole("button", { name: "Save override" }).click();
    await expect(
      page.getByRole("status").filter({ hasText: "could not be completed" }),
    ).toBeVisible();
    await expect(page.getByRole("combobox", { name: /^Override/ })).toHaveValue(
      "PAID",
    );
    await expect(
      page.getByLabel("Expires at (UTC; blank means 30 days)"),
    ).toHaveValue(expires);
    await expect(
      page.getByRole("combobox", { name: /^Reason/ }).first(),
    ).toHaveValue("SECURITY");
  } finally {
    await pool.query(
      `DROP TRIGGER "${trigger}" ON "AdminAuditLog"; DROP FUNCTION "${trigger}"()`,
    );
  }
  const rolledBack = await pool.query(
    `SELECT "planOverride" FROM "User" WHERE id=$1`,
    [operator.target],
  );
  expect(rolledBack.rows[0].planOverride).toBeNull();
  expect(
    (
      await pool.query(
        `SELECT count(*)::int AS n FROM "AdminAuditSafe" WHERE "targetIdSnapshot"=$1 AND action='PLAN_OVERRIDE'`,
        [operator.target],
      )
    ).rows[0].n,
  ).toBe(0);
  await page.getByRole("button", { name: "Save override" }).click();
  await expect(
    page.getByRole("status").filter({ hasText: "Change saved." }),
  ).toBeVisible();
  expect(requests).toHaveLength(2);
  expect(requests[0]).toBe(requests[1]);
  expect(
    (
      await pool.query(
        `SELECT count(*)::int AS n FROM "AdminAuditSafe" WHERE "targetIdSnapshot"=$1 AND action='PLAN_OVERRIDE'`,
        [operator.target],
      )
    ).rows[0].n,
  ).toBe(1);
});
